import { Component } from '@angular/core';
import { Application } from 'src/app/auth/Models/Application';
import { Company } from 'src/app/landing/models/company';
import { Job } from 'src/app/landing/models/job';
import { ApplicationService } from 'src/app/service/application/application.service';
import { CompanyService } from 'src/app/service/company/company.service';

@Component({
  selector: 'app-dashboard',
  templateUrl: './dashboard.component.html',
  styleUrls: ['./dashboard.component.css']
})
export class DashboardComponent {
  ngOnInit() {
  console.log("ID:", localStorage.getItem("Id"));
  console.log("Token:", localStorage.getItem("token"));

  this.getCompanyById();
  this.getJobsByCompany();
  this.getApplicantsByCompany();
  this.getPendingApplications();
  this.getHiredApplicants();
}

  company!:Company;
  jobs:Job[] = [];
  applications:Application[] = [];
  pendingApplications :Application[] = [];
  approvedAppplications:Application[] = [];

  constructor(private compService:CompanyService , private appService:ApplicationService){}

  getCompanyById(){
    this.compService.getCompanyById( Number(localStorage.getItem("Id"))).subscribe(
      (res)=>
          this.company = res
    )
  }

  getJobsByCompany(){
    this.compService.getJobsByCompany(Number(localStorage.getItem("Id"))).subscribe(
      (res)=>
          this.jobs = res
    )
  }

  getApplicantsByCompany(){
    this.appService.getApplicantsByCompany(Number(localStorage.getItem("Id"))).subscribe(
      (res)=>
          this.applications = res
    )
  }

  getPendingApplications(){
    this.appService.getPendindApplicants(Number(localStorage.getItem("Id"))).subscribe(
      (res)=>
          this.pendingApplications = res
    )
  }

  getHiredApplicants(){
    this.appService.getHiredApplicants(Number(localStorage.getItem("Id"))).subscribe(
      (res)=>
          this.approvedAppplications = res
    )
  }
}
<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Company Dashboard · HireHub</title>
<link rel="preconnect" href="https://fonts.googleapis.com">
  <link href="https://fonts.googleapis.com/css2?family=Fraunces:opsz,wght@9..144,500;9..144,600;9..144,700&family=Inter:wght@400;500;600;700&family=JetBrains+Mono:wght@400;500;600;700&display=swap" rel="stylesheet">

</head>
<body>
<div class="page">
<header class="topnav app">
  <div class="wrap">
    <a href="company-dashboard.html" class="brand"><span class="brand-dot"></span>HireHub</a>
    <nav class="nav-links app-links">
      <a href="company-dashboard.html" class="active">Dashboard</a>
      <a href="company-post-job.html">Post a Job</a>
      <a href="company-manage-jobs.html">Manage Jobs</a>
      <a href="company-applicants.html">Applicants</a>
      <a href="company-profile.html">Company Profile</a>
    </nav>
    <div class="avatar">NC</div>
  </div>
</header>
<div class="app-shell">
<aside class="sidebar">
  <div class="sidebar-group">
    <span class="sidebar-label">General</span>
    <a href="company-dashboard.html" class="active"><span class="dot"></span>Dashboard</a>
    <a href="company-profile.html"><span class="dot"></span>Company Profile</a>
  </div>
  <div class="sidebar-group">
    <span class="sidebar-label">Hiring</span>
    <a href="company-post-job.html"><span class="dot"></span>Post a Job</a>
    <a href="company-manage-jobs.html"><span class="dot"></span>Manage Jobs</a>
    <a href="company-applicants.html"><span class="dot"></span>Applicants</a>
  </div>
</aside>
<main class="main">

<div class="page-title">{{company?.companyName}}</div>
<div class="page-sub">Hiring overview</div>
<div style="margin-bottom:24px;"><a href="company-post-job.html" class="btn btn-primary">Post a job</a></div>
<div class="card-row-3" style="margin-bottom:16px;">
  <div class="stat-card"><div class="n">{{jobs.length}}</div><div class="l">Active jobs</div></div>
  <div class="stat-card"><div class="n">{{applications.length}}</div><div class="l">Total applicants</div></div>
  <div class="stat-card"><div class="n">{{pendingApplications.length}}</div><div class="l">Pending review</div><span class="sub">needs action</span></div>
</div>
<div class="card-row-3" style="margin-bottom:32px;grid-template-columns:1fr;max-width:220px;">
  <div class="stat-card"><div class="n">{{approvedAppplications.length}}</div><div class="l">Hired</div></div>
</div>
<div class="section-head"><h2>Your jobs</h2></div>
<div class="table-wrap" style="margin-bottom:32px;">
  <table>
    <thead><tr><th>Role</th><th>Posted</th><th>Applicants</th><th>Status</th></tr></thead>
    <tbody>
      <tr *ngFor="let job of jobs"><td>{{job.jobTitle}}</td><td>3 days ago</td><td>31</td><td><span class="chip chip-open">Open</span></td></tr>
      <tr><td>DevOps Engineer</td><td>1 week ago</td><td>18</td><td><span class="chip chip-open">Open</span></td></tr>
      <tr><td>Support Engineer</td><td>3 weeks ago</td><td>64</td><td><span class="chip chip-closed">Closed</span></td></tr>
    </tbody>
  </table>
</div>
<div class="section-head"><h2>Latest applicants</h2></div>
<div class="card-row">
  <div class="card"><div style="display:flex;justify-content:space-between;"><h3 style="font-size:15px;">Aditi Menon</h3><span class="chip chip-pending">Pending</span></div><p class="muted" style="font-size:13px;margin-top:6px;">Backend Engineer · 2 hrs ago</p></div>
  <div class="card"><div style="display:flex;justify-content:space-between;"><h3 style="font-size:15px;">Rohan Iyer</h3><span class="chip chip-pending">Pending</span></div><p class="muted" style="font-size:13px;margin-top:6px;">DevOps Engineer · 5 hrs ago</p></div>
</div>

</main>
</div>
</div>
</body>
</html>
